import{_ as i,W as e,s as d,u as r,ah as s,I as t,w as o,Z as a,A as n}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const x=JSON.parse('{"title":"AppFlowy：Notion 的开源替代品 | LCTT x X-CMD","titleTemplate":false,"description":"AppFlowy：Notion 的开源替代品 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"AppFlowy：Notion 的开源替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"AppFlowy：Notion 的开源替代品 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220718 AppFlowy- An Open-Source Alternative to Notion","title":"AppFlowy：Notion 的开源替代品","tag":"202208"},"relativePath":"202208/20220718 AppFlowy- An Open-Source Alternative to Notion.md","filePath":"[post].md"}'),u={name:"202208/20220718 AppFlowy- An Open-Source Alternative to Notion.md"};function w(y,p,f,g,h,m){const l=e("Link");return r(),d("div",null,[p[25]||(p[25]=s('<h1 id="appflowy-notion-的开源替代品" tabindex="-1">AppFlowy：Notion 的开源替代品 <a class="header-anchor" href="#appflowy-notion-的开源替代品" aria-label="Permalink to AppFlowy：Notion 的开源替代品">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/02/102316f1g6p369uyeeybgo.jpg" alt=""></p><blockquote><p>AppFlowy 旨在成为 Notion 的开源替代品，为你提供更好的隐私保护。让我们了解一下它。</p></blockquote><p>虽然项目管理/笔记工具 Notion 功能非常出色，但它并不是一个开源解决方案。此外，它没有 Linux 桌面客户端。</p><p>那么，对于 Linux 用户来说，更透明、更私密和可用的替代方案是什么？</p><p>这就是 AppFlowy 大放异彩的地方！</p><p>AppFlowy 使用 Rust 和 Flutter 构建，遵循极简原则，但提供了足够的调整空间。</p><h3 id="appflowy-是隐私和用户体验的完美结合" tabindex="-1">AppFlowy 是隐私和用户体验的完美结合 <a class="header-anchor" href="#appflowy-是隐私和用户体验的完美结合" aria-label="Permalink to AppFlowy 是隐私和用户体验的完美结合">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/AppFlowy.png" alt="appflowy"></p>',9)),t("p",null,[p[1]||(p[1]=o("AppFlowy 是相当新的。在它去年首次推出后，我们曾 ")),a(l,{href:"https://news.itsfoss.com/appflowy-development/"},{default:n(()=>p[0]||(p[0]=[o("报告")])),_:1}),p[2]||(p[2]=o(" 了它的发展状况。"))]),t("p",null,[p[4]||(p[4]=o("这是一个开源项目，旨在克服 ")),a(l,{href:"https://www.notion.so/"},{default:n(()=>p[3]||(p[3]=[o("Notion")])),_:1}),p[5]||(p[5]=o(" 在安全和隐私方面的一些限制。它可以帮助你管理任务、添加待办事项列表、截止日期、跟踪事件、添加页面，以及为你的笔记/任务设置文本格式。"))]),p[26]||(p[26]=s(`<p>不仅仅是安全性。用户体验也很重要。而 AppFlowy 在这方面做得很好，甚至比 Notion 更好。</p><p>请注意，该项目仍处于 <strong>测试阶段</strong>。</p><p>目前，该项目的目标不是提供更好的设计和功能，而是数据隐私、原生体验和社区驱动。</p><h3 id="notion-与-appflowy-如何选择" tabindex="-1">Notion 与 AppFlowy，如何选择？ <a class="header-anchor" href="#notion-与-appflowy-如何选择" aria-label="Permalink to Notion 与 AppFlowy，如何选择？">​</a></h3><p>虽然它旨在作为取代 Notion 的开源解决方案，但它可能并不适合所有人。</p><p>因此，如果你要选择 AppFlowy 而不是 Notion，你将获得以下好处：</p><h4 id="透明度" tabindex="-1">透明度 <a class="header-anchor" href="#透明度" aria-label="Permalink to 透明度">​</a></h4><p>AppFlowy 是一个开源项目，因此你可以随时查看和修改代码。</p><h4 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to 隐私">​</a></h4><p>作为闭源软件，Notion 可以直接访问你在云中的私有数据。与之相比，你可以根据自己的喜好自行托管 AppFlowy。</p><p>你的所有个人数据都将保留在你身边，你可以完全控制它。开发人员还提到他们正在使用离线模式来更好的支持本地安装。</p><h4 id="性能和原生体验" tabindex="-1">性能和原生体验 <a class="header-anchor" href="#性能和原生体验" aria-label="Permalink to 性能和原生体验">​</a></h4><p>AppFlowy 使用 Rust 和 Flutter 构建，在提供现代用户体验的同时将性能置于优先位置。</p><p>不仅限于此，你还可以在 Linux 上获得良好的原生体验，这是 Notion 所没有的。</p><h3 id="appflowy-的功能" tabindex="-1">AppFlowy 的功能 <a class="header-anchor" href="#appflowy-的功能" aria-label="Permalink to AppFlowy 的功能">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/appflowy-screenshot-1.png" alt="appflowy screenshot 1"></p><p>AppFlowy 在功能方面可能并不优越，但它确实提供了基本的功能。</p><p>随着开发的继续，你可以期待它会添加更多的功能。一些现有的功能包括：</p><ul><li>原生的跨平台支持。</li><li>能够自行托管或将其安装在你的本地计算机上。</li><li>可定制。</li><li>数据隐私（重中之重）。</li><li>单一代码库，便于更好地维护。</li><li>社区驱动的可扩展性。</li><li>简约的用户界面。</li><li>可以添加待办事项、管理任务。</li><li>文本高亮和基本的格式化。</li><li>用于编辑单元格/网格的键盘快捷键。</li><li>支持深色模式。</li></ul><h4 id="在-linux-上安装-appflowy" tabindex="-1">在 Linux 上安装 AppFlowy <a class="header-anchor" href="#在-linux-上安装-appflowy" aria-label="Permalink to 在 Linux 上安装 AppFlowy">​</a></h4><p>由于它仍处于测试阶段，在默认仓库中还不可用，并且没有维护任何 PPA，也没有 Flatpak/Snap 包。</p><p>但是，你可以通过给定的命令轻松安装 AppFlowy（仅在 Ubuntu 20.04 LTS 和 Arch X86_64 上测试过）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wget https://github.com/AppFlowy-IO/AppFlowy/releases/download/0.0.4/AppFlowy-linux-x86.tar.gz</span></span>
<span class="line"><span>tar -xzvf AppFlowy-linux-x86.tar.gz</span></span>
<span class="line"><span>cd AppFlowy</span></span></code></pre></div><p>要运行 AppFlowy，请使用该命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./app_flowy</span></span></code></pre></div><p>要在你的系统菜单中注册 AppFlowy，你必须执行以下附加步骤：</p><p>首先，你必须更改 AppFlowy 徽标的默认名称：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mv flowy_logo.svg app_flowy.svg</span></span></code></pre></div><p>现在，你必须将 Linux 桌面文件模板复制为正式的 Linux 桌面文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp appflowy.desktop.temp app_flowy.desktop</span></span></code></pre></div><p>然后对配置文件进行一些更改。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo nano appflowy.desktop</span></span></code></pre></div><p>在这里，你必须将 <code>[CHANGE_THIS]</code> 替换为图标和可执行文件的对应路径。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/Add-location-of-icon-and-exec-file-800x524.png" alt="add location of icon and exec file"></p><p>使用 <code>CTRL + O</code> 保存更改并使用 <code>CTRL + X</code> 退出。</p><p>最后，移动桌面文件，以便你的系统可以读取它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mv app_flowy.desktop ~/.local/share/applications/.</span></span></code></pre></div><p>它应该是这样的：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/AppFlowy-in-System-menu-1.png" alt="appflowy in system menu"></p>`,39)),t("p",null,[p[7]||(p[7]=o("无论哪种情况，你都可以查看 AppFlowy 的 ")),a(l,{href:"https://appflowy.gitbook.io/docs/essential-documentation/contribute-to-appflowy/software-contributions/environment-setup/building-on-linux"},{default:n(()=>p[6]||(p[6]=[o("官方文档")])),_:1}),p[8]||(p[8]=o(" 以从源代码构建它。在其官方网站上了解更多关于它的信息。"))]),t("blockquote",null,[t("p",null,[t("strong",null,[a(l,{href:"https://www.appflowy.io/"},{default:n(()=>p[9]||(p[9]=[o("AppFlowy")])),_:1})])])]),p[27]||(p[27]=t("h3",{id:"总结",tabindex:"-1"},[o("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to 总结"},"​")],-1)),p[28]||(p[28]=t("p",null,"如果你需要具有原生 Linux 体验的简单的类 Notion 应用，AppFlowy 是一个有趣的选择。",-1)),p[29]||(p[29]=t("p",null,"考虑到它正在积极开发中，并且远非 Notion 的完全替代品，肯定会出现一些错误/问题。",-1)),p[30]||(p[30]=t("p",null,"作为 Notion 的开源替代品？它可以的！你可以使用它来管理任务、添加笔记和制作待办事项列表。",-1)),p[31]||(p[31]=t("hr",null,null,-1)),t("p",null,[p[11]||(p[11]=o("via: ")),a(l,{href:"https://itsfoss.com/appflowy/"},{default:n(()=>p[10]||(p[10]=[o("https://itsfoss.com/appflowy/")])),_:1})]),t("p",null,[p[16]||(p[16]=o("作者：")),a(l,{href:"https://itsfoss.com/author/sagar/"},{default:n(()=>p[12]||(p[12]=[o("Sagar Sharma")])),_:1}),p[17]||(p[17]=o(" 选题：")),a(l,{href:"https://github.com/lkxed"},{default:n(()=>p[13]||(p[13]=[o("lkxed")])),_:1}),p[18]||(p[18]=o(" 译者：")),a(l,{href:"https://github.com/geekpi"},{default:n(()=>p[14]||(p[14]=[o("geekpi")])),_:1}),p[19]||(p[19]=o(" 校对：")),a(l,{href:"https://github.com/wxy"},{default:n(()=>p[15]||(p[15]=[o("wxy")])),_:1})]),t("p",null,[p[22]||(p[22]=o("本文由 ")),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>p[20]||(p[20]=[o("LCTT")])),_:1}),p[23]||(p[23]=o(" 原创编译，")),a(l,{href:"https://linux.cn/"},{default:n(()=>p[21]||(p[21]=[o("Linux中国")])),_:1}),p[24]||(p[24]=o(" 荣誉推出"))])])}const F=i(u,[["render",w]]);export{x as __pageData,F as default};
